#include "position.hpp"


/*
 * helpers
 */
static inline void calculate_pbb(Board& board, bit_board_t* bb) {
	uint32_t tmp; uint8_t tm;
	bit_board_t mask = 0b1;

	bb[0] = 0x0000000000000000ULL;	bb[1] = 0x0000000000000000ULL;
	bb[2] = 0x0000000000000000ULL;	bb[3] = 0x0000000000000000ULL;
	bb[4] = 0x0000000000000000ULL;	bb[5] = 0x0000000000000000ULL;
	bb[6] = 0x0000000000000000ULL;	bb[7] = 0x0000000000000000ULL;
	bb[8] = 0x0000000000000000ULL;

	for (uint8_t y = 0; y < 8; y++, mask <<= 8) {
		tmp = board[y];
		for (uint8_t x = 0; x < 32; x += 4) {
			tm = (tmp >> x) & 0xF;
			if (!(tm & ALL)) { continue; }
			bb[tm & ALL] |= mask << (x >> 2);
			if (tm & BLK)	{ bb[BLK] |= mask << (x >> 2); }
			else			{ bb[WHT] |= mask << (x >> 2); }
		}
	}

	bb[ALL] = bb[BLK] | bb[WHT];
}


/*
 * Position
 */
Position::Position(Board& board, color_t stm, uint8_t castle) {
	this->board = board;
	calculate_pbb(board, pieces);

	this->en_passant_sq =	0;
	this->side_to_move =	stm;
	this->castle_rights =	(castle_t)castle;
	update_slider_blockers(stm);
	update_slider_blockers(!stm);
	uint8_t ksq = CTZ(piece(stm, KING));
	checkers = attackers_to(ksq) & piece(!stm, ALL);
}

void Position::update_slider_blockers(color_t color) {
	uint8_t ksq = CTZ(piece(color, KING));
	this->king_blockers[color] =	0;
	this->pinners[!color] =			0;

	bit_board_t sliders = (
		((pseudo_rook_attacks[ksq] &	(pieces[ROOK] | pieces[QUEEN]))		|
		(pseudo_bishop_attacks[ksq] &	(pieces[BISHOP] | pieces[QUEEN])))	&
		pieces[(!color) << 3]	// any sliding pieces of the opponent on the a path to the king
	);
	bit_board_t occupancy = pieces[ALL] ^ sliders;

	bit_board_t bb;
	for (uint8_t sq; sliders;) {
		sq = pop_lsb(sliders);
		bb = between_bb[ksq][sq] & occupancy;

		if (bb & !(bb - 1)) {  // if one
			king_blockers[color] |= bb;
			if (bb & pieces[color << 3]) {
				pinners[!color] |= (1 << sq);
			}
		}
	}
}


bit_board_t Position::piece(piece_t piece) const {
	return pieces[piece];
}

bit_board_t Position::piece(color_t color, piece_t piece) const {
	return pieces[piece] & pieces[color << 3];
}

bit_board_t Position::attackers_to(uint8_t sq, color_t color) const {
	return (
		(index_magic_rook(sq, pieces[ALL]) &	(pieces[color << 3] & (pieces[ROOK] | pieces[QUEEN])))		|
		(index_magic_bishop(sq, pieces[ALL]) &	(pieces[color << 3] & (pieces[BISHOP] | pieces[QUEEN])))	|
		(pawn_attacks[color][sq] & piece(!color, PAWN))														|
		(knight_attacks[sq] & piece(color, KNIGHT))	|	(king_attacks[sq] & piece(color, KING))
	);
}
bit_board_t Position::attackers_to(uint8_t sq) const {
	return (
		(index_magic_rook(sq, pieces[ALL]) &	(pieces[ROOK] | pieces[QUEEN]))		|
		(index_magic_bishop(sq, pieces[ALL]) &	(pieces[BISHOP] | pieces[QUEEN]))	|
		(pawn_attacks[BLACK][sq] & piece(WHITE, PAWN))								|
		(pawn_attacks[WHITE][sq] & piece(BLACK, PAWN))								|
		(knight_attacks[sq] & pieces[KNIGHT])	|	(king_attacks[sq] & pieces[KING])
	);
}


// used to test for special cases (EN_PASSANT, CASTLE, KING move, pinned move)
// NOTE: it is assumed that the move is otherwise correct (in release mode)
bool Position::legal(const Move move) const {
	assert(move.is_ok());

    uint8_t from = move.src();
    uint8_t to   = move.dst();
	uint8_t type = move.type();

	assert(piece(side_to_move, ALL) & (1ULL << from));			// piece can move
	assert(!(piece(side_to_move, ALL) & (1ULL << to)));			// does not capture same color

	if (type == EN_PASSANT) {
        uint8_t		ksq	= CTZ(piece(side_to_move, KING));
        uint8_t		cap	= to - pawn_push(side_to_move);
        bit_board_t	occ = (pieces[ALL] ^ (0b1ULL << from) ^ (0b1ULL << cap)) | (0b1ULL << to);

        assert((0b1ULL << to) & 0x0000FF0000FF0000ULL);			// attacks possible en passant square
        assert((0b1ULL << from) & piece(side_to_move, PAWN));	// is a pawn
        assert((0b1ULL << cap) & piece(!side_to_move, PAWN));	// captures a pawn
        assert(!((0b1ULL << to) & pieces[ALL]));				// no double capture

		return (
			!(index_magic_rook(ksq, occ) &		(pieces[ROOK] | pieces[QUEEN]))		&&
			!(index_magic_bishop(ksq, occ) &	(pieces[BISHOP] | pieces[QUEEN]))
		);
	}

	if (type == CASTLE) {
		assert(to == ((to > from ? 6 : 2) ^ (side_to_move * 0x38)));  // check if to square is valid
		// TODO: can castle?

		int8_t step = to > from ? -1 : 1;
		for (uint8_t sq = to; sq != from; sq += step) {
			if (attackers_to(sq, !side_to_move)) { return false; }
		}

		return true;
	}

	if (piece(side_to_move, KING) & (0b1ULL << from)) {
		return !attackers_to(to, !side_to_move);
	}

    return (
		!(king_blockers[side_to_move] & from) ||			// is not a blocker
		(line_bb[from][to] & piece(side_to_move, KING))		// moves along the line of attack
	);

}



bit_board_t Position::king_blockers_g(color_t color) const {
	return this->king_blockers[color];
}

bit_board_t Position::checkers_g(void) const {
	return this->checkers;
}

color_t Position::side_to_move_g(void) const {
	return this->side_to_move;
}

sq_t Position::en_passant_sq_g(void) const {
	return this->en_passant_sq;
}

castle_t Position::can_castle(castle_t castle) const {
	return castle & this->castle_rights;
}

bool Position::castle_impeded(castle_t castle) const {
	return castle_masks[CTZ(castle)] & pieces[ALL];
}

sq_t Position::castling_rook_square(castle_t castle) const {
	return castle_rsq[CTZ(castle)];
}
sq_t Position::castling_king_square(castle_t castle) const {
	return castle_ksq[CTZ(castle)];
}



